insert into public.questions (exam_category, subject, topic, type, difficulty, body, body_hi, question_data, options, marks_correct, marks_wrong, explanation, explanation_hi, concept_group_id, source_type, source_citation, status)
values
('upsc','History','Music & Dance','statement_based','medium','Consider the following statements about Kathakali:','कथकली के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It is a dance-drama of Kerala.", "Its roles were traditionally performed by male actors.", "The colours of its make-up indicate the nature of each character."], "statements_hi": ["यह केरल का नृत्य-नाटक है।", "इसकी भूमिकाएँ पारंपरिक रूप से पुरुष कलाकार निभाते थे।", "इसकी रूप-सज्जा के रंग हर पात्र के स्वभाव का संकेत देते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. Kathakali, which grew from Ramanattam and Krishnanattam in 17th-century Kerala, tells stories from the epics through codified hand gestures, facial expression and vigorous movement, to the beat of the chenda and maddalam drums; all roles, including women''s, were played by men. Its make-up is among the most elaborate in the world and works as a code -- green ''pacha'' for noble heroes, ''kathi'' (knife) for arrogant villains, red beard for the demonic -- with huge skirts and headgear.','तीनों कथन सही हैं। 17वीं सदी के केरल में रामनाट्टम और कृष्णनाट्टम से विकसित कथकली महाकाव्यों की कथाएँ संहिताबद्ध हस्त-मुद्राओं, चेहरे के भावों और ज़ोरदार गतियों से चेंडा और मद्दलम ढोलों की थाप पर कहती है; स्त्रियों सहित सारी भूमिकाएँ पुरुष निभाते थे। इसकी रूप-सज्जा विश्व की सबसे विस्तृत में है और एक संकेत-भाषा का काम करती है: कुलीन नायकों के लिए हरा ''पच्चा'', अहंकारी खलनायकों के लिए ''कत्ति'' (छुरी), राक्षसी पात्रों के लिए लाल दाढ़ी, और साथ में विशाल घाघरे तथा शिरोभूषण।','art-kathakali','original_pattern_matched','Centre for Cultural Resources and Training (CCRT), Ministry of Culture -- Indian classical dance and music; Sangeet Natak Akademi -- classical dance forms.','draft'),
('upsc','History','Music & Dance','statement_based','medium','Consider the following statements about Odissi:','ओडिसी के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The ''chowk'' and the ''tribhangi'' are its two basic postures.", "It developed at the court of the Mughals in Delhi.", "The ''Gotipua'' tradition of Odissi is performed by young women."], "statements_hi": ["''चौक'' और ''त्रिभंगी'' इसकी दो मूल मुद्राएँ (आसन) हैं।", "इसका विकास दिल्ली में मुग़लों के दरबार में हुआ।", "ओडिसी की ''गोटिपुआ'' परंपरा युवतियाँ निभाती हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: the square, masculine chowk and the feminine tribhangi, with the body bent at neck, waist and knee, are the foundation of Odissi''s sculptural style. Statement 2 is wrong: Odissi grew from the temple dance of the maharis (devadasis) of the Jagannath temple at Puri, and dancing figures appear in the Udayagiri caves and temple sculpture from centuries earlier. Statement 3 is wrong: gotipuas are young boys dressed as girls, who took over when the mahari tradition declined; many great Odissi gurus, including Kelucharan Mohapatra, began as gotipuas.','केवल कथन 1 सही है: चौकोर, पुरुषोचित चौक और गर्दन, कमर तथा घुटने पर मुड़े शरीर वाली स्त्रियोचित त्रिभंगी ओडिसी की मूर्तिवत शैली की नींव हैं। कथन 2 गलत है: ओडिसी पुरी के जगन्नाथ मंदिर की महारियों (देवदासियों) के मंदिर-नृत्य से विकसित हुई, और नृत्य करती आकृतियाँ उदयगिरि गुफाओं और मंदिर-मूर्तिकला में सदियों पहले से दिखती हैं। कथन 3 गलत है: गोटिपुआ लड़कियों के वेश में युवा लड़के होते हैं, जिन्होंने महारी परंपरा के पतन पर उसकी जगह ली; केलुचरण महापात्र सहित कई महान ओडिसी गुरुओं ने गोटिपुआ के रूप में शुरुआत की।','art-odissi','original_pattern_matched','Centre for Cultural Resources and Training (CCRT), Ministry of Culture -- Indian classical dance and music; Sangeet Natak Akademi -- classical dance forms.','draft'),
('upsc','History','Music & Dance','statement_based','medium','Consider the following statements about Manipuri dance:','मणिपुरी नृत्य के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It is closely linked with Vaishnava devotion and the Ras Lila of Krishna.", "The ''Pung cholom'' is a dance performed while playing the drum.", "Manipuri dancers traditionally do not wear ankle bells."], "statements_hi": ["यह वैष्णव भक्ति और कृष्ण की रासलीला से गहराई से जुड़ा है।", "''पुंग चोलोम'' ढोल बजाते हुए किया जाने वाला नृत्य है।", "मणिपुरी नर्तक पारंपरिक रूप से घुंघरू नहीं पहनते।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. After Vaishnavism spread in Manipur in the 18th century, King Bhagyachandra is credited with shaping the Ras Lila, whose dancers wear a stiff, barrel-shaped skirt (potloi). The pung cholom, in which drummers leap and whirl while playing, and the martial Thang-ta show the vigorous side of Manipuri tradition. The dancers'' soft, rounded movements, with feet that barely strike the ground and no ghungroos, set Manipuri apart from most other classical forms.','तीनों कथन सही हैं। 18वीं सदी में मणिपुर में वैष्णव धर्म फैलने के बाद राजा भाग्यचंद्र को रासलीला को आकार देने का श्रेय दिया जाता है, जिसकी नर्तकियाँ कड़ा, पीपे जैसा घाघरा (पोटलोई) पहनती हैं। पुंग चोलोम, जिसमें ढोलवादक बजाते हुए उछलते और घूमते हैं, और युद्धक थांग-ता मणिपुरी परंपरा का ओजस्वी पक्ष दिखाते हैं। नर्तकों की कोमल, गोलाकार गतियाँ, जिनमें पैर ज़मीन पर मुश्किल से पड़ते हैं और घुंघरू नहीं होते, मणिपुरी को अधिकांश दूसरे शास्त्रीय रूपों से अलग करती हैं।','art-manipuri-dance','original_pattern_matched','Centre for Cultural Resources and Training (CCRT), Ministry of Culture -- Indian classical dance and music; Sangeet Natak Akademi -- classical dance forms.','draft'),
('upsc','History','Music & Dance','statement_based','medium','Consider the following statements about Mohiniyattam:','मोहिनीअट्टम के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It is a classical dance of Kerala.", "It is a graceful solo dance in the ''lasya'' style, traditionally performed by women.", "It is performed to Hindustani music."], "statements_hi": ["यह केरल का शास्त्रीय नृत्य है।", "यह ''लास्य'' शैली का एक सुंदर एकल नृत्य है, जिसे पारंपरिक रूप से स्त्रियाँ करती हैं।", "यह हिंदुस्तानी संगीत पर किया जाता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Named after Mohini, the enchantress form of Vishnu, Mohiniyattam is marked by gentle, swaying movements of the torso, a white and gold costume and a side-bun hairstyle; the poet Vallathol revived it through the Kerala Kalamandalam in the 1930s. Statement 3 is wrong: it is performed to Carnatic music, sung in the slow Sopana style of Kerala''s temples, with lyrics in Manipravalam, a mix of Malayalam and Sanskrit.','कथन 1 और 2 सही हैं। विष्णु के मोहिनी रूप पर नामित मोहिनीअट्टम धड़ की कोमल, लहराती गतियों, सफ़ेद और सुनहरी वेशभूषा और एक ओर बँधे जूड़े के लिए जाना जाता है; कवि वल्लत्तोल ने 1930 के दशक में केरल कलामंडलम के ज़रिए इसे पुनर्जीवित किया। कथन 3 गलत है: यह कर्नाटक संगीत पर, केरल के मंदिरों की धीमी सोपान शैली में गाया जाता है, और इसके बोल मणिप्रवालम में होते हैं, जो मलयालम और संस्कृत का मिश्रण है।','art-mohiniyattam','original_pattern_matched','Centre for Cultural Resources and Training (CCRT), Ministry of Culture -- Indian classical dance and music; Sangeet Natak Akademi -- classical dance forms.','draft'),
('upsc','History','Music & Dance','statement_based','medium','Consider the following statements about Indian classical music:','भारतीय शास्त्रीय संगीत के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Tyagaraja, Muthuswami Dikshitar and Syama Sastri are known as the ''Trinity'' of Carnatic music.", "The ''thaat'' system of classifying Hindustani ragas was worked out by Tyagaraja.", "Hindustani music leaves no room for improvisation, and performers sing only fixed compositions."], "statements_hi": ["त्यागराज, मुत्तुस्वामी दीक्षितार और श्यामा शास्त्री कर्नाटक संगीत की ''त्रिमूर्ति'' कहलाते हैं।", "हिंदुस्तानी रागों को वर्गीकृत करने की ''थाट'' प्रणाली त्यागराज ने तैयार की।", "हिंदुस्तानी संगीत में तात्कालिक रचना (improvisation) की कोई जगह नहीं है, और कलाकार केवल निश्चित रचनाएँ गाते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: the three composers, all born in Tiruvarur in the 18th century, created much of the Carnatic concert repertoire. Statement 2 is wrong: the ten-thaat classification of Hindustani ragas was set out by Vishnu Narayan Bhatkhande in the early 20th century. Statement 3 is wrong: improvisation -- the slow unfolding of a raga in alap, and elaborations such as taans -- is at the heart of Hindustani performance, as it is in Carnatic music.','केवल कथन 1 सही है: 18वीं सदी में तिरुवारूर में जन्मे तीनों संगीतकारों ने कर्नाटक संगीत-सभा के अधिकांश भंडार की रचना की। कथन 2 गलत है: हिंदुस्तानी रागों का दस-थाट वर्गीकरण 20वीं सदी के आरंभ में विष्णु नारायण भातखंडे ने प्रस्तुत किया। कथन 3 गलत है: तात्कालिक रचना, यानी आलाप में राग का धीरे-धीरे विस्तार और तान जैसे अलंकरण, हिंदुस्तानी प्रस्तुति का केंद्र है, जैसे कर्नाटक संगीत में।','art-classical-music-trinity-thaat','original_pattern_matched','Centre for Cultural Resources and Training (CCRT), Ministry of Culture -- Indian classical dance and music -- Hindustani and Carnatic music.','draft'),
('upsc','History','Music & Dance','statement_based','medium','According to the classification of musical instruments in the Natya Shastra, consider the following statements:','नाट्यशास्त्र में वाद्ययंत्रों के वर्गीकरण के अनुसार निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The sitar is an ''avanaddha vadya'' (membranophone).", "The flute is a ''ghana vadya'' (solid instrument).", "The tabla is a ''tata vadya'' (stringed instrument)."], "statements_hi": ["सितार एक ''अवनद्ध वाद्य'' (झिल्ली वाला वाद्य) है।", "बाँसुरी एक ''घन वाद्य'' (ठोस वाद्य) है।", "तबला एक ''तत वाद्य'' (तार वाद्य) है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": true}]'::jsonb,2,0.66,'None of the statements is correct. The Natya Shastra groups instruments into four classes: tata (stringed, such as the sitar, veena and sarod), sushira (wind, such as the flute and shehnai), avanaddha (covered with skin, such as the tabla, mridangam and dholak) and ghana (solid, struck against each other, such as cymbals, the ghatam and the jaltarang''s bowls). Each statement puts an instrument into another class; the system anticipates the modern classification of chordophones, aerophones, membranophones and idiophones.','कोई भी कथन सही नहीं है। नाट्यशास्त्र वाद्यों को चार वर्गों में रखता है: तत (तार वाले, जैसे सितार, वीणा और सरोद), सुषिर (फूँक वाले, जैसे बाँसुरी और शहनाई), अवनद्ध (खाल से मढ़े, जैसे तबला, मृदंगम और ढोलक) और घन (ठोस, आपस में टकराकर बजने वाले, जैसे मंजीरा, घटम और जलतरंग के कटोरे)। हर कथन किसी वाद्य को दूसरे वर्ग में रख देता है; यह प्रणाली तार, वायु, झिल्ली और ठोस वाद्यों के आधुनिक वर्गीकरण का पूर्वाभास है।','art-natya-shastra-instrument-classes','original_pattern_matched','Centre for Cultural Resources and Training (CCRT), Ministry of Culture -- Indian classical dance and music -- musical instruments of India.','draft'),
('upsc','History','Music & Dance','statement_based','medium','Consider the following statements about Chhau:','छऊ के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Its three main styles are named after Seraikela, Mayurbhanj and Purulia.", "Mayurbhanj Chhau is performed without masks.", "It is on UNESCO''s list of the intangible cultural heritage of humanity."], "statements_hi": ["इसकी तीन मुख्य शैलियों के नाम सरायकेला, मयूरभंज और पुरुलिया पर हैं।", "मयूरभंज छऊ बिना मुखौटों के किया जाता है।", "यह UNESCO की मानवता की अमूर्त सांस्कृतिक धरोहर सूची में है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. Chhau, found in Jharkhand, Odisha and West Bengal and inscribed on UNESCO''s intangible heritage list in 2010, draws on martial practice and the epics; Seraikela and Purulia dancers wear masks -- Purulia''s huge and brightly painted -- while Mayurbhanj dancers do not. Chhau is traditionally danced by men, often in groups, at spring festivals such as Chaitra Parva.','तीनों कथन सही हैं। झारखंड, ओडिशा और पश्चिम बंगाल में मिलने वाला और 2010 में UNESCO की अमूर्त धरोहर सूची में शामिल छऊ युद्ध-अभ्यास और महाकाव्यों पर आधारित है; सरायकेला और पुरुलिया के नर्तक मुखौटे पहनते हैं, पुरुलिया के विशाल और चटकीले रंगे, जबकि मयूरभंज के नर्तक नहीं पहनते। छऊ पारंपरिक रूप से पुरुष, प्रायः समूहों में, चैत्र पर्व जैसे वसंत-उत्सवों पर करते हैं।','art-chhau','original_pattern_matched','Centre for Cultural Resources and Training (CCRT), Ministry of Culture -- Indian classical dance and music; UNESCO -- Chhau dance (2010).','draft'),
('upsc','History','Music & Dance','statement_based','medium','Consider the following statements about the Sangeet Natak Akademi:','संगीत नाटक अकादमी के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It recognises eight Indian dance forms as classical.", "It was set up by the Government of India in the early 1950s.", "It is a body created by the Constitution."], "statements_hi": ["यह आठ भारतीय नृत्य-रूपों को शास्त्रीय के रूप में मान्यता देती है।", "इसकी स्थापना भारत सरकार ने 1950 के दशक के आरंभ में की।", "यह संविधान द्वारा बनाया गया निकाय है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. The Akademi, India''s national academy of music, dance and drama, was created by a government resolution in 1952 and inaugurated in 1953; it recognises Bharatanatyam, Kathak, Kathakali, Kuchipudi, Manipuri, Mohiniyattam, Odissi and Sattriya as classical dances and gives the Sangeet Natak Akademi awards. Statement 3 is wrong: it is an autonomous body registered as a society and funded by the Ministry of Culture, not a constitutional body.','कथन 1 और 2 सही हैं। संगीत, नृत्य और नाटक की भारत की राष्ट्रीय अकादमी 1952 में सरकारी प्रस्ताव से बनी और 1953 में उद्घाटित हुई; यह भरतनाट्यम, कथक, कथकली, कुचिपुड़ी, मणिपुरी, मोहिनीअट्टम, ओडिसी और सत्रिया को शास्त्रीय नृत्यों के रूप में मान्यता देती है और संगीत नाटक अकादमी पुरस्कार देती है। कथन 3 गलत है: यह संस्था के रूप में पंजीकृत और संस्कृति मंत्रालय द्वारा वित्तपोषित एक स्वायत्त निकाय है, संवैधानिक निकाय नहीं।','art-sangeet-natak-akademi','original_pattern_matched','Sangeet Natak Akademi -- classical dance forms; Ministry of Culture -- autonomous bodies.','draft'),
('upsc','History','Music & Dance','statement_based','medium','Consider the following statements about the qawwali:','क़व्वाली के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It is closely associated with the Chishti order of Sufis.", "Tradition credits Amir Khusrau with shaping it.", "It is performed at Sufi shrines (dargahs)."], "statements_hi": ["यह सूफ़ियों के चिश्ती सिलसिले से गहराई से जुड़ी है।", "परंपरा इसे आकार देने का श्रेय अमीर ख़ुसरो को देती है।", "यह सूफ़ी दरगाहों पर प्रस्तुत की जाती है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. The Chishtis, unlike some other orders, embraced sama -- listening to devotional music -- as a way to spiritual ecstasy, and the qawwali grew out of it, blending Persian and Indian melodic traditions; Amir Khusrau, disciple of Nizamuddin Auliya, is credited with many of its forms. Qawwalis are sung at dargahs such as Ajmer and Nizamuddin, especially at the urs.','तीनों कथन सही हैं। कुछ दूसरे सिलसिलों के विपरीत चिश्तियों ने आध्यात्मिक आनंद के मार्ग के रूप में समा, यानी भक्ति-संगीत सुनना, अपनाया, और क़व्वाली इसी से विकसित हुई, जिसमें फ़ारसी और भारतीय स्वर-परंपराएँ घुली-मिली हैं; निज़ामुद्दीन औलिया के शिष्य अमीर ख़ुसरो को इसके कई रूपों का श्रेय दिया जाता है। क़व्वालियाँ अजमेर और निज़ामुद्दीन जैसी दरगाहों पर, विशेषकर उर्स पर, गाई जाती हैं।','art-qawwali-chishti','original_pattern_matched','Centre for Cultural Resources and Training (CCRT), Ministry of Culture -- Indian classical dance and music; NCERT Class XII, Themes in Indian History II -- Bhakti-Sufi Traditions.','draft'),
('upsc','History','Music & Dance','statement_based','easy','Consider the following statements about folk dances:','लोक नृत्यों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Garba is a folk dance of Punjab.", "Bihu is a folk dance of Kerala.", "Ghoomar is a folk dance of Tamil Nadu."], "statements_hi": ["गरबा पंजाब का लोक नृत्य है।", "बिहू केरल का लोक नृत्य है।", "घूमर तमिलनाडु का लोक नृत्य है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": true}]'::jsonb,2,0.66,'None of the statements is correct. Garba, danced in circles around a lamp during Navratri, belongs to Gujarat; Bihu, danced at the spring festival of Bohag Bihu, belongs to Assam; and Ghoomar, with its swirling skirts, belongs to Rajasthan. Punjab is known for Bhangra and Giddha, Kerala for Thiruvathirakali, and Tamil Nadu for Kummi and Karagattam.','कोई भी कथन सही नहीं है। नवरात्रि में दीपक के चारों ओर घेरे में किया जाने वाला गरबा गुजरात का है; बोहाग बिहू के वसंत-उत्सव पर किया जाने वाला बिहू असम का है; और घूमते घाघरों वाला घूमर राजस्थान का है। पंजाब भांगड़ा और गिद्धा के लिए, केरल तिरुवातिराकली के लिए, और तमिलनाडु कुम्मी और करगट्टम के लिए जाना जाता है।','art-folk-dances-states','original_pattern_matched','Centre for Cultural Resources and Training (CCRT), Ministry of Culture -- Indian classical dance and music -- folk dances of India.','draft'),
('upsc','History','Music & Dance','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Bharatanatyam is performed to Carnatic music.", "The name Kathak comes from ''katha'', a story."], "statements_hi": ["भरतनाट्यम कर्नाटक संगीत पर किया जाता है।", "कथक नाम ''कथा'', यानी कहानी, से आया है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct. Bharatanatyam''s music comes from the Carnatic tradition, with the nattuvanar keeping rhythm with cymbals; its modern form owes much to the Thanjavur Quartet and to Rukmini Devi Arundale. Kathak began with the kathakars, travelling storytellers who narrated epic tales through song and gesture, and later developed at royal courts.','दोनों कथन सही हैं। भरतनाट्यम का संगीत कर्नाटक परंपरा से आता है, जिसमें नट्टुवनार झाँझ से ताल रखता है; इसका आधुनिक रूप तंजावुर चौकड़ी और रुक्मिणी देवी अरुंडेल का बहुत ऋणी है। कथक की शुरुआत कथाकारों से हुई, यानी घूमते कथावाचक जो गीत और हाव-भाव से महाकाव्यों की कथाएँ सुनाते थे, और बाद में यह राजदरबारों में विकसित हुआ।','art-bharatanatyam-kathak-basics','original_pattern_matched','Centre for Cultural Resources and Training (CCRT), Ministry of Culture -- Indian classical dance and music; Sangeet Natak Akademi -- classical dance forms.','draft'),
('upsc','History','Music & Dance','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Yakshagana is a traditional theatre form of Karnataka.", "Theyyam is a ritual performance of Assam."], "statements_hi": ["यक्षगान कर्नाटक का पारंपरिक रंगमंच है।", "तेय्यम असम की एक अनुष्ठानिक प्रस्तुति है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: Yakshagana, from coastal and Malnad Karnataka, combines dance, music, dialogue and elaborate costumes to present epic stories, often through the night. Statement 2 is wrong: Theyyam is a ritual dance-worship of north Kerala (the Kolathunadu region), in which the performer is believed to become the deity; Assam''s ritual theatre is the Ankiya Naat of Sankardeva.','केवल कथन 1 सही है: तटीय और मलनाड कर्नाटक का यक्षगान नृत्य, संगीत, संवाद और विस्तृत वेशभूषा को मिलाकर, प्रायः रात भर, महाकाव्यों की कथाएँ प्रस्तुत करता है। कथन 2 गलत है: तेय्यम उत्तरी केरल (कोलत्तुनाडु क्षेत्र) की अनुष्ठानिक नृत्य-पूजा है, जिसमें माना जाता है कि कलाकार स्वयं देवता बन जाता है; असम का अनुष्ठानिक रंगमंच शंकरदेव का अंकिया नाट है।','art-yakshagana-theyyam','original_pattern_matched','Centre for Cultural Resources and Training (CCRT), Ministry of Culture -- Indian classical dance and music -- theatre forms of India.','draft'),
('upsc','History','Music & Dance','statement_based','easy','Consider the following statements about Lavani:','लावणी के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It is a folk form of Rajasthan.", "It is traditionally accompanied by the dholki."], "statements_hi": ["यह राजस्थान का लोक रूप है।", "इसके साथ पारंपरिक रूप से ढोलकी बजाई जाती है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 2 is correct. Lavani, a fast song-and-dance form known for its powerful rhythm and nine-yard saree, is from Maharashtra, where it was popular in the Peshwa period and in the Tamasha theatre; the dholki drum drives its tempo. Rajasthan''s folk forms include Ghoomar and Kalbelia.','केवल कथन 2 सही है। अपनी प्रबल ताल और नौवारी साड़ी के लिए प्रसिद्ध तेज़ गीत-नृत्य लावणी महाराष्ट्र का है, जहाँ यह पेशवा काल में और तमाशा रंगमंच में लोकप्रिय था; ढोलकी इसकी गति को संचालित करती है। राजस्थान के लोक रूपों में घूमर और कालबेलिया हैं।','art-lavani','original_pattern_matched','Centre for Cultural Resources and Training (CCRT), Ministry of Culture -- Indian classical dance and music -- folk dances of India.','draft'),
('upsc','History','Music & Dance','statement_based','easy','Consider the following statements about Kathak:','कथक के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Its main gharanas are those of Lucknow, Jaipur and Banaras.", "Rapid spins (chakkars) are a feature of Kathak.", "Birju Maharaj belonged to the Jaipur gharana."], "statements_hi": ["इसके मुख्य घराने लखनऊ, जयपुर और बनारस के हैं।", "तेज़ चक्कर कथक की एक विशेषता हैं।", "बिरजू महाराज जयपुर घराने के थे।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. The Lucknow gharana stresses grace and expression (abhinaya), the Jaipur gharana rhythmic virtuosity and footwork, and the Banaras gharana its own blend; chakkars and intricate footwork with ghungroos are Kathak''s hallmarks. Statement 3 is wrong: Birju Maharaj (1938-2022) was the leading figure of the Lucknow (Kalka-Bindadin) gharana.','कथन 1 और 2 सही हैं। लखनऊ घराना लालित्य और भाव (अभिनय) पर ज़ोर देता है, जयपुर घराना लयकारी और पदचालन पर, और बनारस घराना अपने मिश्रण पर; चक्कर और घुंघरुओं के साथ जटिल पदचालन कथक की पहचान हैं। कथन 3 गलत है: बिरजू महाराज (1938-2022) लखनऊ (कालका-बिंदादीन) घराने की प्रमुख हस्ती थे।','art-kathak-gharanas','original_pattern_matched','Centre for Cultural Resources and Training (CCRT), Ministry of Culture -- Indian classical dance and music; Sangeet Natak Akademi -- classical dance forms.','draft'),
('upsc','History','Music & Dance','statement_based','hard','Consider the following statements about the Natya Shastra and aesthetics:','नाट्यशास्त्र और सौंदर्यशास्त्र के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It explains ''rasa'' as arising from the combination of emotions (bhavas) presented on stage.", "It names eight rasas; ''shanta'' (peace) was added as the ninth by later theorists.", "It is a treatise on music alone."], "statements_hi": ["यह ''रस'' को मंच पर प्रस्तुत भावों के मेल से उत्पन्न बताता है।", "यह आठ रसों के नाम देता है; ''शांत'' को बाद के सिद्धांतकारों ने नौवें रस के रूप में जोड़ा।", "यह केवल संगीत का ग्रंथ है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. In the Natya Shastra''s famous rasa sutra, rasa -- the aesthetic relish felt by the spectator -- arises from the union of determinants, consequents and transitory states of emotion. It lists eight rasas (erotic, comic, pathetic, furious, heroic, terrible, odious and marvellous); later thinkers such as Abhinavagupta argued for shanta as a ninth, giving the ''navarasa''. Statement 3 is wrong: the text covers drama as a whole -- theatre design, acting, dance, music, costume and make-up.','कथन 1 और 2 सही हैं। नाट्यशास्त्र के प्रसिद्ध रस-सूत्र में रस, यानी दर्शक द्वारा अनुभूत सौंदर्यात्मक आस्वाद, विभावों, अनुभावों और व्यभिचारी भावों के संयोग से उत्पन्न होता है। यह आठ रस गिनाता है (शृंगार, हास्य, करुण, रौद्र, वीर, भयानक, वीभत्स और अद्भुत); अभिनवगुप्त जैसे बाद के चिंतकों ने नौवें रस के रूप में शांत का पक्ष लिया, जिससे ''नवरस'' बने। कथन 3 गलत है: यह ग्रंथ पूरे नाट्य को शामिल करता है: रंगमंच की रचना, अभिनय, नृत्य, संगीत, वेशभूषा और रूप-सज्जा।','art-natya-shastra-rasa','original_pattern_matched','Centre for Cultural Resources and Training (CCRT), Ministry of Culture -- Indian classical dance and music; A.L. Basham, The Wonder That Was India, chapter on the arts.','draft'),
('upsc','History','Music & Dance','statement_based','hard','Consider the following statements about the composers of the Carnatic ''Trinity'':','कर्नाटक संगीत की ''त्रिमूर्ति'' के संगीतकारों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Tyagaraja composed mainly in Telugu.", "Muthuswami Dikshitar composed mainly in Kannada.", "Syama Sastri composed mainly in Hindi."], "statements_hi": ["त्यागराज ने मुख्यतः तेलुगु में रचनाएँ कीं।", "मुत्तुस्वामी दीक्षितार ने मुख्यतः कन्नड़ में रचनाएँ कीं।", "श्यामा शास्त्री ने मुख्यतः हिंदी में रचनाएँ कीं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: Tyagaraja''s devotional kritis to Rama, including the Pancharatna kritis sung every year at the Tiruvaiyaru festival, are mostly in Telugu. Statement 2 is wrong: Muthuswami Dikshitar composed mostly in Sanskrit, and his music also shows the influence of the Hindustani music he heard at Varanasi, and even of Western band tunes. Statement 3 is wrong: Syama Sastri, a priest devoted to the goddess Kamakshi, composed in Telugu and Sanskrit and was known for his mastery of rhythm.','केवल कथन 1 सही है: राम के प्रति त्यागराज की भक्तिपूर्ण कृतियाँ, जिनमें हर वर्ष तिरुवैयारु उत्सव में गाई जाने वाली पंचरत्न कृतियाँ भी हैं, अधिकतर तेलुगु में हैं। कथन 2 गलत है: मुत्तुस्वामी दीक्षितार ने अधिकतर संस्कृत में रचनाएँ कीं, और उनके संगीत में वाराणसी में सुने हिंदुस्तानी संगीत, और पश्चिमी बैंड-धुनों तक, का प्रभाव भी है। कथन 3 गलत है: देवी कामाक्षी को समर्पित पुजारी श्यामा शास्त्री ने तेलुगु और संस्कृत में रचनाएँ कीं और वे ताल पर अपनी महारत के लिए जाने जाते थे।','art-carnatic-trinity-languages','original_pattern_matched','Centre for Cultural Resources and Training (CCRT), Ministry of Culture -- Indian classical dance and music -- Carnatic music.','draft'),
('upsc','History','Music & Dance','statement_based','hard','Consider the following statements about Dhrupad:','ध्रुपद के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It was traditionally sung in four styles (banis): Gauhar, Dagur, Khandar and Nauhar.", "The Dagar family has been one of the best-known lineages of Dhrupad singers.", "A Dhrupad performance begins with an alap sung without rhythmic accompaniment."], "statements_hi": ["यह पारंपरिक रूप से चार शैलियों (बानियों) में गाया जाता था: गौहर, डागुर, खंडार और नौहार।", "डागर परिवार ध्रुपद गायकों की सबसे प्रसिद्ध परंपराओं में से एक रहा है।", "ध्रुपद प्रस्तुति बिना ताल-संगत के गाए जाने वाले आलाप से शुरू होती है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. Dhrupad, the oldest surviving form of Hindustani vocal music, is austere and meditative; the four banis are said to derive from the styles of singers at Akbar''s court. The Dagar family, which has kept the Dagarvani alive over some twenty generations, revived Dhrupad in the 20th century. The long, unmeasured alap, sung on syllables such as ''nom'' and ''tom'', is followed by the composition with the pakhawaj drum.','तीनों कथन सही हैं। हिंदुस्तानी गायन का सबसे पुराना बचा हुआ रूप ध्रुपद गंभीर और ध्यानमय है; कहा जाता है कि चारों बानियाँ अकबर के दरबार के गायकों की शैलियों से निकलीं। लगभग बीस पीढ़ियों से डागरवाणी को जीवित रखने वाले डागर परिवार ने 20वीं सदी में ध्रुपद को पुनर्जीवित किया। ''नोम'' और ''तोम'' जैसे अक्षरों पर गाया जाने वाला लंबा, बिना ताल का आलाप पखावज के साथ रचना से पहले आता है।','art-dhrupad-banis-dagar','original_pattern_matched','Centre for Cultural Resources and Training (CCRT), Ministry of Culture -- Indian classical dance and music -- Hindustani music.','draft'),
('upsc','History','Music & Dance','statement_based','hard','Consider the following statements about ragas and talas:','रागों और तालों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["In Hindustani music, ragas are traditionally associated with particular times of the day.", "A tala is measured in units called ''matras''.", "A raga with a given name always has the same scale in Hindustani and Carnatic music."], "statements_hi": ["हिंदुस्तानी संगीत में राग पारंपरिक रूप से दिन के विशेष समयों से जुड़े होते हैं।", "ताल ''मात्रा'' नाम की इकाइयों में मापा जाता है।", "किसी नाम का राग हिंदुस्तानी और कर्नाटक संगीत में हमेशा एक ही स्वर-क्रम (scale) वाला होता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. By the time theory (samay), Bhairav is a dawn raga and Yaman an evening raga, and some ragas belong to seasons, such as Malhar to the monsoon. Talas are cycles of matras -- Teentaal has 16, Jhaptaal 10, Rupak 7 -- with the first beat (sam) as the point of return. Statement 3 is wrong: the two systems developed separately, and the same name can stand for different scales -- Carnatic Hindolam, for example, corresponds to Hindustani Malkauns, while Hindustani Hindol is a different raga.','कथन 1 और 2 सही हैं। समय-सिद्धांत के अनुसार भैरव प्रभात का और यमन संध्या का राग है, और कुछ राग ऋतुओं के हैं, जैसे मल्हार वर्षा का। ताल मात्राओं के चक्र हैं, जैसे तीनताल में 16, झपताल में 10, रूपक में 7, और पहली मात्रा (सम) लौटने का बिंदु होती है। कथन 3 गलत है: दोनों प्रणालियाँ अलग-अलग विकसित हुईं, और एक ही नाम अलग-अलग स्वर-क्रमों का हो सकता है; उदाहरण के लिए, कर्नाटक का हिंदोलम हिंदुस्तानी मालकौंस के समान है, जबकि हिंदुस्तानी हिंडोल एक अलग राग है।','art-raga-time-tala-matra','original_pattern_matched','Centre for Cultural Resources and Training (CCRT), Ministry of Culture -- Indian classical dance and music -- Hindustani and Carnatic music.','draft'),
('upsc','History','Music & Dance','mcq','medium','The ''thumri'', a light classical form of Hindustani vocal music, flourished especially at the court of:','हिंदुस्तानी गायन का उपशास्त्रीय रूप ''ठुमरी'' विशेष रूप से किसके दरबार में फला-फूला?','{}'::jsonb,'[{"id": "a", "body": "Raja Man Singh Tomar of Gwalior", "body_hi": "ग्वालियर के राजा मान सिंह तोमर", "isCorrect": false}, {"id": "b", "body": "Krishnadevaraya of Vijayanagara", "body_hi": "विजयनगर के कृष्णदेवराय", "isCorrect": false}, {"id": "c", "body": "Wajid Ali Shah of Awadh", "body_hi": "अवध के वाजिद अली शाह", "isCorrect": true}, {"id": "d", "body": "Ranjit Singh of Punjab", "body_hi": "पंजाब के रणजीत सिंह", "isCorrect": false}]'::jsonb,2,0.66,'The thumri, romantic and devotional in mood and closely tied to Kathak, flourished at Lucknow under Nawab Wajid Ali Shah in the mid-19th century, and later in Banaras. Man Singh Tomar of Gwalior is associated with the patronage of Dhrupad -- the distractor that plays on the idea of a musical court.','भावुक और भक्तिपूर्ण मिज़ाज वाली और कथक से गहराई से जुड़ी ठुमरी 19वीं सदी के मध्य में नवाब वाजिद अली शाह के अधीन लखनऊ में, और बाद में बनारस में, फली-फूली। ग्वालियर के मान सिंह तोमर ध्रुपद के संरक्षण से जुड़े हैं; यह गलत विकल्प संगीतमय दरबार के विचार से खेलता है।','art-thumri-wajid-ali-shah','original_pattern_matched','Centre for Cultural Resources and Training (CCRT), Ministry of Culture -- Indian classical dance and music -- Hindustani music.','draft'),
('upsc','History','Music & Dance','mcq','medium','The ''tillana'', a lively rhythmic piece usually performed at the end of a recital, belongs to:','''तिल्लाना'', जो सामान्यतः प्रस्तुति के अंत में की जाने वाली जीवंत, लयप्रधान रचना है, किससे संबंधित है?','{}'::jsonb,'[{"id": "a", "body": "Carnatic music and Bharatanatyam", "body_hi": "कर्नाटक संगीत और भरतनाट्यम", "isCorrect": true}, {"id": "b", "body": "Hindustani khayal of the Gwalior gharana", "body_hi": "ग्वालियर घराने का हिंदुस्तानी ख़याल", "isCorrect": false}, {"id": "c", "body": "Kathakali", "body_hi": "कथकली", "isCorrect": false}, {"id": "d", "body": "The Ras Lila of Manipur", "body_hi": "मणिपुर की रासलीला", "isCorrect": false}]'::jsonb,2,0.66,'The tillana, built mainly on rhythmic syllables with a short lyric, closes a Bharatanatyam margam with brisk footwork and sculptural poses; it is the Carnatic counterpart of the Hindustani ''tarana'', which is the natural trap for anyone who knows the tarana.','मुख्यतः लयात्मक अक्षरों और एक छोटे गीत पर बना तिल्लाना तेज़ पदचालन और मूर्तिवत मुद्राओं के साथ भरतनाट्यम के मार्गम को समाप्त करता है; यह हिंदुस्तानी ''तराना'' का कर्नाटक समकक्ष है, जो तराना जानने वाले के लिए स्वाभाविक जाल है।','art-tillana','original_pattern_matched','Centre for Cultural Resources and Training (CCRT), Ministry of Culture -- Indian classical dance and music; Sangeet Natak Akademi -- classical dance forms.','draft'),
('upsc','History','Music & Dance','mcq','medium','Ustad Bismillah Khan is famous for playing the:','उस्ताद बिस्मिल्लाह ख़ाँ किस वाद्य को बजाने के लिए प्रसिद्ध हैं?','{}'::jsonb,'[{"id": "a", "body": "Sarod", "body_hi": "सरोद", "isCorrect": false}, {"id": "b", "body": "Sitar", "body_hi": "सितार", "isCorrect": false}, {"id": "c", "body": "Pakhawaj", "body_hi": "पखावज", "isCorrect": false}, {"id": "d", "body": "Shehnai", "body_hi": "शहनाई", "isCorrect": true}]'::jsonb,2,0.66,'Bismillah Khan (1916-2006) raised the shehnai, an instrument of temple and wedding music, to the classical concert stage; he played at the Red Fort on the first Independence Day in 1947 and received the Bharat Ratna in 2001. He was closely identified with Varanasi and its ghats.','बिस्मिल्लाह ख़ाँ (1916-2006) ने मंदिर और विवाह-संगीत के वाद्य शहनाई को शास्त्रीय संगीत-सभा के मंच तक पहुँचाया; उन्होंने 1947 में पहले स्वतंत्रता दिवस पर लाल क़िले पर वादन किया और 2001 में भारत रत्न पाया। उनकी पहचान वाराणसी और उसके घाटों से गहराई से जुड़ी थी।','art-bismillah-khan-shehnai','original_pattern_matched','Centre for Cultural Resources and Training (CCRT), Ministry of Culture -- Indian classical dance and music; Ministry of Home Affairs -- Bharat Ratna awardees.','draft'),
('upsc','History','Music & Dance','mcq','medium','The ''Hastalakshana Deepika'', a text on hand gestures, is followed above all in:','हस्त-मुद्राओं पर ग्रंथ ''हस्तलक्षण दीपिका'' का पालन मुख्य रूप से किसमें होता है?','{}'::jsonb,'[{"id": "a", "body": "Kathak", "body_hi": "कथक", "isCorrect": false}, {"id": "b", "body": "Kathakali", "body_hi": "कथकली", "isCorrect": true}, {"id": "c", "body": "Manipuri", "body_hi": "मणिपुरी", "isCorrect": false}, {"id": "d", "body": "Bharatanatyam", "body_hi": "भरतनाट्यम", "isCorrect": false}]'::jsonb,2,0.66,'Kathakali''s elaborate gesture language, capable of carrying whole sentences of dialogue, is based largely on the 24 basic mudras of the Hastalakshana Deepika, while Bharatanatyam draws more on the Abhinaya Darpana of Nandikeshvara. The gesture code is one reason Kathakali can tell long stories without spoken words.','पूरे संवाद-वाक्य कह सकने वाली कथकली की विस्तृत मुद्रा-भाषा मुख्यतः हस्तलक्षण दीपिका की 24 मूल मुद्राओं पर आधारित है, जबकि भरतनाट्यम नंदिकेश्वर के अभिनय दर्पण पर अधिक निर्भर है। यही मुद्रा-संहिता एक कारण है कि कथकली बिना बोले शब्दों के लंबी कथाएँ कह सकती है।','art-hastalakshana-deepika-kathakali','original_pattern_matched','Centre for Cultural Resources and Training (CCRT), Ministry of Culture -- Indian classical dance and music; Sangeet Natak Akademi -- classical dance forms.','draft'),
('upsc','History','Music & Dance','mcq','medium','Who is regarded as the ''father'' (Pitamaha) of Carnatic music?','कर्नाटक संगीत का ''पितामह'' किसे माना जाता है?','{}'::jsonb,'[{"id": "a", "body": "Tyagaraja", "body_hi": "त्यागराज", "isCorrect": false}, {"id": "b", "body": "Annamacharya", "body_hi": "अन्नमाचार्य", "isCorrect": false}, {"id": "c", "body": "Purandaradasa", "body_hi": "पुरंदरदास", "isCorrect": true}, {"id": "d", "body": "Swathi Thirunal", "body_hi": "स्वाति तिरुनाल", "isCorrect": false}]'::jsonb,2,0.66,'Purandaradasa (16th century), a Haridasa saint of the Vijayanagara period, systematised the teaching of Carnatic music through graded lessons -- sarali varisai, alankaras and geetams -- still used by beginners, and chose the raga Mayamalavagowla for first lessons. Tyagaraja came two centuries later; Annamacharya composed Telugu songs to Venkateshwara; and Swathi Thirunal was a 19th-century king-composer of Travancore.','विजयनगर काल के हरिदास संत पुरंदरदास (16वीं सदी) ने क्रमबद्ध पाठों, यानी सरली वरिसै, अलंकार और गीतम, के ज़रिए कर्नाटक संगीत की शिक्षा को व्यवस्थित किया, जिनका उपयोग आज भी शुरुआती विद्यार्थी करते हैं, और पहले पाठों के लिए माया मालवगौल राग चुना। त्यागराज दो सदी बाद आए; अन्नमाचार्य ने वेंकटेश्वर पर तेलुगु गीत रचे; और स्वाति तिरुनाल त्रावणकोर के 19वीं सदी के राजा-संगीतकार थे।','art-purandaradasa-pitamaha','original_pattern_matched','Centre for Cultural Resources and Training (CCRT), Ministry of Culture -- Indian classical dance and music -- Carnatic music.','draft'),
('upsc','History','Music & Dance','mcq','easy','Ustad Zakir Hussain was a renowned player of the:','उस्ताद ज़ाकिर हुसैन किस वाद्य के प्रसिद्ध वादक थे?','{}'::jsonb,'[{"id": "a", "body": "Tabla", "body_hi": "तबला", "isCorrect": true}, {"id": "b", "body": "Santoor", "body_hi": "संतूर", "isCorrect": false}, {"id": "c", "body": "Sarangi", "body_hi": "सारंगी", "isCorrect": false}, {"id": "d", "body": "Veena", "body_hi": "वीणा", "isCorrect": false}]'::jsonb,2,0.66,'Zakir Hussain (1951-2024), son of the tabla maestro Alla Rakha, took the tabla to world audiences through classical concerts and fusion groups such as Shakti, and won several Grammy awards. The santoor is associated with Shivkumar Sharma and the sarangi with Ram Narayan.','तबला उस्ताद अल्ला रक्खा के पुत्र ज़ाकिर हुसैन (1951-2024) शास्त्रीय संगीत-सभाओं और शक्ति जैसे फ़्यूज़न समूहों के ज़रिए तबले को विश्व के श्रोताओं तक ले गए और कई ग्रैमी पुरस्कार जीते। संतूर शिवकुमार शर्मा से और सारंगी राम नारायण से जुड़ी है।','art-zakir-hussain-tabla','original_pattern_matched','Centre for Cultural Resources and Training (CCRT), Ministry of Culture -- Indian classical dance and music; Sangeet Natak Akademi -- classical dance forms.','draft'),
('upsc','History','Music & Dance','mcq','easy','M.S. Subbulakshmi, the first musician to receive the Bharat Ratna, was a vocalist of:','भारत रत्न पाने वाली पहली संगीतकार एम.एस. सुब्बुलक्ष्मी किस संगीत की गायिका थीं?','{}'::jsonb,'[{"id": "a", "body": "Hindustani music", "body_hi": "हिंदुस्तानी संगीत", "isCorrect": false}, {"id": "b", "body": "Rabindra Sangeet", "body_hi": "रवींद्र संगीत", "isCorrect": false}, {"id": "c", "body": "Qawwali", "body_hi": "क़व्वाली", "isCorrect": false}, {"id": "d", "body": "Carnatic music", "body_hi": "कर्नाटक संगीत", "isCorrect": true}]'::jsonb,2,0.66,'M.S. Subbulakshmi (1916-2004) of Madurai, whose renditions of the Venkateswara Suprabhatam and Meera bhajans are famous, was a Carnatic vocalist; she sang at the United Nations General Assembly in 1966 and received the Bharat Ratna in 1998.','मदुरै की एम.एस. सुब्बुलक्ष्मी (1916-2004), जिनके वेंकटेश्वर सुप्रभातम और मीरा भजनों के गायन प्रसिद्ध हैं, कर्नाटक संगीत की गायिका थीं; उन्होंने 1966 में संयुक्त राष्ट्र महासभा में गाया और 1998 में भारत रत्न पाया।','art-ms-subbulakshmi','original_pattern_matched','Ministry of Home Affairs -- Bharat Ratna awardees; Sangeet Natak Akademi.','draft'),
('upsc','History','Music & Dance','mcq','hard','The ''Sangita Ratnakara'', a major thirteenth-century treatise on music, was written by:','संगीत पर 13वीं सदी का प्रमुख ग्रंथ ''संगीत रत्नाकर'' किसने लिखा?','{}'::jsonb,'[{"id": "a", "body": "Bharata Muni", "body_hi": "भरत मुनि", "isCorrect": false}, {"id": "b", "body": "Sarngadeva", "body_hi": "शार्ङ्गदेव", "isCorrect": true}, {"id": "c", "body": "Matanga", "body_hi": "मतंग", "isCorrect": false}, {"id": "d", "body": "Vishnu Narayan Bhatkhande", "body_hi": "विष्णु नारायण भातखंडे", "isCorrect": false}]'::jsonb,2,0.66,'Sarngadeva wrote the Sangita Ratnakara at the court of the Yadava king Singhana at Devagiri; written before the split between the northern and southern systems, it is revered as an authority by both Hindustani and Carnatic musicians. Bharata''s Natya Shastra and Matanga''s Brihaddeshi are older texts, and Bhatkhande belongs to the 20th century.','शार्ङ्गदेव ने देवगिरि में यादव राजा सिंघण के दरबार में संगीत रत्नाकर लिखा; उत्तरी और दक्षिणी प्रणालियों के अलग होने से पहले लिखे जाने के कारण हिंदुस्तानी और कर्नाटक, दोनों के संगीतकार इसे प्रमाण मानते हैं। भरत का नाट्यशास्त्र और मतंग का बृहद्देशी पुराने ग्रंथ हैं, और भातखंडे 20वीं सदी के हैं।','art-sangita-ratnakara-sarngadeva','original_pattern_matched','Centre for Cultural Resources and Training (CCRT), Ministry of Culture -- Indian classical dance and music -- history of Indian music.','draft'),
('upsc','History','Music & Dance','mcq','hard','''Kutiyattam'', among the first Indian traditions recognised by UNESCO as a masterpiece of intangible heritage, is a form of Sanskrit theatre from:','UNESCO द्वारा अमूर्त धरोहर की उत्कृष्ट कृति के रूप में मान्यता पाने वाली पहली भारतीय परंपराओं में से एक ''कूडियाट्टम'' कहाँ का संस्कृत रंगमंच है?','{}'::jsonb,'[{"id": "a", "body": "Karnataka", "body_hi": "कर्नाटक", "isCorrect": false}, {"id": "b", "body": "Odisha", "body_hi": "ओडिशा", "isCorrect": false}, {"id": "c", "body": "Kerala", "body_hi": "केरल", "isCorrect": true}, {"id": "d", "body": "Tamil Nadu", "body_hi": "तमिलनाडु", "isCorrect": false}]'::jsonb,2,0.66,'Kutiyattam, performed by the Chakyar and Nangiar communities in Kerala''s temple theatres (koothambalams), is perhaps the oldest living form of Sanskrit drama; a single act can take many nights to perform, with elaborate hand gestures and eye movements. UNESCO proclaimed it a Masterpiece of the Oral and Intangible Heritage of Humanity in 2001.','केरल के मंदिर-रंगमंचों (कूत्तंबलम) में चाक्यार और नंगियार समुदायों द्वारा प्रस्तुत कूडियाट्टम संभवतः संस्कृत नाटक का सबसे पुराना जीवित रूप है; विस्तृत हस्त-मुद्राओं और नेत्र-गतियों के साथ एक अंक की प्रस्तुति में कई रातें लग सकती हैं। UNESCO ने 2001 में इसे मानवता की मौखिक और अमूर्त धरोहर की उत्कृष्ट कृति घोषित किया।','art-kutiyattam-kerala','original_pattern_matched','UNESCO -- Kutiyattam, Sanskrit theatre (2001/2008); Sangeet Natak Akademi.','draft'),
('upsc','History','Music & Dance','match_the_following','medium','Consider the following pairs of musicians and the instruments they are known for:','संगीतकारों और उनके प्रसिद्ध वाद्यों के निम्नलिखित युग्मों पर विचार कीजिए:','{"list_1": ["1. Hariprasad Chaurasia", "2. Shivkumar Sharma", "3. Ravi Shankar", "4. Amjad Ali Khan"], "list_1_hi": ["1. हरिप्रसाद चौरसिया", "2. शिवकुमार शर्मा", "3. रविशंकर", "4. अमजद अली ख़ाँ"], "list_2": ["Flute", "Santoor", "Sarod", "Sarod"], "list_2_hi": ["बाँसुरी", "संतूर", "सरोद", "सरोद"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": true}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": false}]'::jsonb,2,0.66,'Three pairs are correct. Hariprasad Chaurasia made the bansuri a leading concert instrument, Shivkumar Sharma brought the Kashmiri santoor into Hindustani classical music, and Amjad Ali Khan of the Senia Bangash lineage is a sarod maestro. Pair 3 is wrong: Ravi Shankar, a disciple of Allauddin Khan of Maihar, was a sitar player who took Indian music to the West; his fellow disciple Ali Akbar Khan, Allauddin''s son, played the sarod -- the family link is the trap.','तीन युग्म सही हैं। हरिप्रसाद चौरसिया ने बाँसुरी को प्रमुख संगीत-सभा वाद्य बनाया, शिवकुमार शर्मा कश्मीरी संतूर को हिंदुस्तानी शास्त्रीय संगीत में लाए, और सेनिया बंगश परंपरा के अमजद अली ख़ाँ सरोद के उस्ताद हैं। युग्म 3 गलत है: मैहर के अलाउद्दीन ख़ाँ के शिष्य रविशंकर सितार वादक थे, जो भारतीय संगीत को पश्चिम तक ले गए; उनके गुरुभाई, अलाउद्दीन के पुत्र अली अकबर ख़ाँ, सरोद बजाते थे; यही पारिवारिक संबंध जाल है।','art-musicians-instruments-pairs','original_pattern_matched','Centre for Cultural Resources and Training (CCRT), Ministry of Culture -- Indian classical dance and music; Sangeet Natak Akademi -- classical dance forms.','draft'),
('upsc','History','Music & Dance','match_the_following','medium','Consider the following pairs of dancers and the classical dance forms they are known for:','नर्तकों और उनके प्रसिद्ध शास्त्रीय नृत्य-रूपों के निम्नलिखित युग्मों पर विचार कीजिए:','{"list_1": ["1. Kelucharan Mohapatra", "2. Birju Maharaj", "3. Kalamandalam Kalyanikutty Amma", "4. Rukmini Devi Arundale"], "list_1_hi": ["1. केलुचरण महापात्र", "2. बिरजू महाराज", "3. कलामंडलम कल्याणीकुट्टी अम्मा", "4. रुक्मिणी देवी अरुंडेल"], "list_2": ["Odissi", "Kathak", "Kathakali", "Kathakali"], "list_2_hi": ["ओडिसी", "कथक", "कथकली", "कथकली"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": true}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": false}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": false}]'::jsonb,2,0.66,'Only pairs 1 and 2 are correct. Kelucharan Mohapatra shaped modern Odissi''s repertoire, and Birju Maharaj was the doyen of Lucknow Kathak. Pair 3 is wrong: Kalamandalam Kalyanikutty Amma is known as the ''mother of Mohiniyattam'' for reviving and codifying it. Pair 4 is wrong: Rukmini Devi Arundale, founder of Kalakshetra in Chennai (1936), revived Bharatanatyam and made it respectable for women of all backgrounds.','केवल युग्म 1 और 2 सही हैं। केलुचरण महापात्र ने आधुनिक ओडिसी के भंडार को आकार दिया, और बिरजू महाराज लखनऊ कथक के शिखर थे। युग्म 3 गलत है: कलामंडलम कल्याणीकुट्टी अम्मा को मोहिनीअट्टम को पुनर्जीवित और संहिताबद्ध करने के लिए ''मोहिनीअट्टम की माँ'' कहा जाता है। युग्म 4 गलत है: चेन्नई में कलाक्षेत्र (1936) की संस्थापक रुक्मिणी देवी अरुंडेल ने भरतनाट्यम को पुनर्जीवित किया और इसे हर पृष्ठभूमि की स्त्रियों के लिए सम्मानजनक बनाया।','art-dancers-forms-pairs','original_pattern_matched','Sangeet Natak Akademi -- classical dance forms.','draft'),
('upsc','History','Music & Dance','match_the_following','easy','Consider the following pairs of puppetry traditions and the States they belong to:','कठपुतली परंपराओं और उनके राज्यों के निम्नलिखित युग्मों पर विचार कीजिए:','{"list_1": ["1. Kathputli", "2. Tholu Bommalata", "3. Ravanachhaya", "4. Putul Nach"], "list_1_hi": ["1. कठपुतली", "2. तोलु बोम्मालाटा", "3. रावणछाया", "4. पुतुल नाच"], "list_2": ["Rajasthan", "Andhra Pradesh", "Odisha", "West Bengal"], "list_2_hi": ["राजस्थान", "आंध्र प्रदेश", "ओडिशा", "पश्चिम बंगाल"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": false}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": true}]'::jsonb,2,0.66,'All four pairs are correct. Kathputli string puppets tell Rajasthani legends; Tholu Bommalata uses large, translucent, coloured leather shadow puppets; Ravanachhaya of Odisha uses small, unpainted deer-skin shadow puppets; and Putul Nach of Bengal uses rod puppets. They illustrate the four main kinds -- string, shadow and rod, as well as glove puppetry such as Pavakathakali of Kerala. A student who expects one mismatch will fall for ''Only three pairs''.','चारों युग्म सही हैं। कठपुतली की धागा-पुतलियाँ राजस्थानी लोककथाएँ सुनाती हैं; तोलु बोम्मालाटा चमड़े की बड़ी, पारभासी, रंगीन छाया-पुतलियों का उपयोग करता है; ओडिशा का रावणछाया हिरण की खाल की छोटी, बिना रंगी छाया-पुतलियों का; और बंगाल का पुतुल नाच छड़-पुतलियों का। ये मुख्य प्रकारों, यानी धागा, छाया और छड़, के साथ केरल के पावाकथकली जैसी दस्ताना-पुतलियों को भी दिखाते हैं। जो विद्यार्थी एक बेमेल की अपेक्षा करता है, वह ''केवल तीन युग्म'' के जाल में फँसेगा।','art-puppetry-states-pairs','original_pattern_matched','Centre for Cultural Resources and Training (CCRT), Ministry of Culture -- Indian classical dance and music -- puppet forms of India.','draft'),
('upsc','History','Music & Dance','match_the_following','hard','Consider the following pairs of folk theatre forms and the States they belong to:','लोक रंगमंच के रूपों और उनके राज्यों के निम्नलिखित युग्मों पर विचार कीजिए:','{"list_1": ["1. Tamasha", "2. Bhavai", "3. Jatra", "4. Nautanki"], "list_1_hi": ["1. तमाशा", "2. भवाई", "3. जात्रा", "4. नौटंकी"], "list_2": ["Maharashtra", "Gujarat", "Assam", "Kerala"], "list_2_hi": ["महाराष्ट्र", "गुजरात", "असम", "केरल"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": true}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": false}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": false}]'::jsonb,2,0.66,'Only pairs 1 and 2 are correct. Tamasha, with its Lavani songs and comic sketches, is Maharashtrian, and Bhavai, a travelling theatre of social satire, belongs to Gujarat. Pair 3 is wrong: Jatra, open-air theatre that grew out of Vaishnava devotion associated with Chaitanya, is the folk theatre of Bengal (and Odisha); Assam''s is the Ankiya Naat or Bhaona. Pair 4 is wrong: Nautanki, with its operatic singing and the nagara drum, belongs to Uttar Pradesh.','केवल युग्म 1 और 2 सही हैं। लावणी गीतों और हास्य-प्रसंगों वाला तमाशा महाराष्ट्र का है, और सामाजिक व्यंग्य का घुमंतू रंगमंच भवाई गुजरात का है। युग्म 3 गलत है: चैतन्य से जुड़ी वैष्णव भक्ति से निकला खुला रंगमंच जात्रा बंगाल (और ओडिशा) का लोक रंगमंच है; असम का अंकिया नाट या भाओना है। युग्म 4 गलत है: गीत-नाट्य शैली और नगाड़े वाली नौटंकी उत्तर प्रदेश की है।','art-folk-theatre-states-pairs','original_pattern_matched','Centre for Cultural Resources and Training (CCRT), Ministry of Culture -- Indian classical dance and music -- theatre forms of India.','draft')
